import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    df['As Of Date'] = pd.to_datetime(df['As Of Date'])
    df['Origination Date'] = pd.to_datetime(df['Origination Date'])

    closed_statuses = [
        'pending', 'declined', 'failed', 'rejected',
        'charged off', 'charged_off', 'charged-off', 'charge off',
        'written off', 'written_off', 'write off',
        'paid off', 'paid_off', 'fully paid', 'closed'
    ]

    # Latest snapshot per loan (any kind), then filter to on-book (sale kind)
    df_sorted = df.sort_values('As Of Date')
    latest_any = df_sorted.groupby('Loan ID').last().reset_index()
    on_book = latest_any[~latest_any['Loan Status'].str.lower().isin(closed_statuses)].copy()
    on_book_sale = on_book[on_book['row_kind'] == 'sale'].copy()

    # NPL: dpd >= 90 or status in non-accrual/nonaccrual/default/defaulted
    npl_statuses = ['non-accrual', 'nonaccrual', 'non_accrual', 'default', 'defaulted']
    on_book_sale['is_npl'] = (
        (on_book_sale['Days Past Due'] >= 90) |
        (on_book_sale['Loan Status'].str.lower().isin(npl_statuses))
    )

    products = on_book_sale['Product'].dropna().unique()
    top_products = (
        on_book_sale.groupby('Product')['Loan ID'].count()
        .nlargest(10).index.tolist()
    )

    npl_results = []
    for prod in top_products:
        grp = on_book_sale[on_book_sale['Product'] == prod]
        total_bal = grp['Outstanding Principal'].sum()
        npl_bal = grp.loc[grp['is_npl'], 'Outstanding Principal'].sum()
        ratio = npl_bal / total_bal if total_bal > 0 else 0.0
        npl_results.append({"name": str(prod), "value": round(float(ratio), 6)})

    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Outstanding Principal",
        "aggregation": "ratio",
        "label": "npl_ratio",
        "results": npl_results
    })

    # Also provide raw Outstanding Principal sum by Product (on-book sale rows)
    bal_results = []
    for prod in top_products:
        grp = on_book_sale[on_book_sale['Product'] == prod]
        total_bal = grp['Outstanding Principal'].sum()
        bal_results.append({"name": str(prod), "value": round(float(total_bal), 2)})

    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Outstanding Principal",
        "aggregation": "sum",
        "label": "total_outstanding_principal",
        "results": bal_results
    })

    # NPL count by product
    npl_count_results = []
    for prod in top_products:
        grp = on_book_sale[on_book_sale['Product'] == prod]
        npl_count = int(grp['is_npl'].sum())
        npl_count_results.append({"name": str(prod), "value": float(npl_count)})

    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Loan ID",
        "aggregation": "count",
        "label": "npl_loan_count",
        "results": npl_count_results
