try:
    import numpy as np

    df['As Of Date'] = pd.to_datetime(df['As Of Date'])
    df['Origination Date'] = pd.to_datetime(df['Origination Date'])

    closed_statuses = ['pending', 'declined', 'failed', 'rejected',
                       'charged off', 'charged_off', 'charged-off', 'charge off',
                       'written off', 'written_off', 'write off',
                       'paid off', 'paid_off', 'fully paid', 'closed']

    df['_status_lower'] = df['Loan Status'].str.lower().str.strip()

    latest_any = (
        df.sort_values('As Of Date')
        .groupby('Loan ID')
        .last()
        .reset_index()
    )
    latest_any['_status_lower'] = latest_any['Loan Status'].str.lower().str.strip()
    on_book_ids = latest_any.loc[
        ~latest_any['_status_lower'].isin(closed_statuses), 'Loan ID'
    ]

    df_sale = df[df['row_kind'] == 'sale'].copy()
    df_sale_onbook = df_sale[df_sale['Loan ID'].isin(on_book_ids)]

    latest_snap = (
        df_sale_onbook.sort_values('As Of Date')
        .groupby('Loan ID')
        .last()
        .reset_index()
    )

    total_balance = latest_snap['Outstanding Principal'].sum()

    delinq_30 = latest_snap[latest_snap['Days Past Due'] >= 30]

    by_product_total = latest_snap.groupby('Product')['Outstanding Principal'].sum()
    by_product_delinq = delinq_30.groupby('Product')['Outstanding Principal'].sum()

    products = by_product_total.index.union(by_product_delinq.index)
    delinq_ratio_by_product = []
    for prod in products:
        total_p = by_product_total.get(prod, 0.0)
        delinq_p = by_product_delinq.get(prod, 0.0)
        ratio = float(delinq_p / total_p) if total_p > 0 else 0.0
        delinq_ratio_by_product.append({"name": str(prod), "value": round(ratio, 6)})

    delinq_ratio_by_product_sorted = sorted(
        delinq_ratio_by_product, key=lambda x: x['value'], reverse=True
    )

    overall_delinq_ratio = float(
        delinq_30['Outstanding Principal'].sum() / total_balance
    ) if total_balance > 0 else 0.0

    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Outstanding Principal",
        "aggregation": "ratio",
        "label": "delinquency_30",
        "results": delinq_ratio_by_product_sorted
    })

    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Outstanding Principal",
        "aggregation": "sum",
        "label": "outstanding_principal_by_product",
        "results": [
            {"name": str(prod), "value": float(round(val, 2))}
            for prod, val in by_product_total.sort_values(ascending=False).items()
        ]
    })

    delinq_balance_by_product = [
        {"name": str(prod), "value": float(round(by_product_delinq.get(prod, 0.0), 2))}
        for prod in by_product_total.sort_values(ascending=False).index
    ]
    result['segments'].append({
        "segment_column": "Product",
        "metric_column": "Outstanding Principal",
        "aggregation": "sum",
        "label": "delinquent_30_balance_by_product",
        "results": delinq_balance_by_product
    })

    result['assumptions'].append(
        "delinquency_30 = sum(Outstanding Principal where DPD>=30) / sum(Outstanding Principal), "
        "using each Loan ID's latest sale-kind snapshot, excluding closed/charged-off/paid-off accounts."
    )
    result['assumptions'].append(
        f"Overall delinquency_30 ratio across all products: {overall_delinq_ratio:.4f}"
    )
    result['assumptions'].append(
        "106 cancel-flagged rows excluded via row_kind filter; 60 DPD sentinel-null rows treated as missing."
    )

except Exception as e:
